package com.example.inventoryservicefeb25.exception;
import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import jakarta.validation.ConstraintViolationException; import java.time.Instant; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(MethodArgumentNotValidException.class) public ResponseEntity<Map<String,Object>> bodyValidation(MethodArgumentNotValidException ex){Map<String,Object>b=new LinkedHashMap<>();b.put("timestamp",Instant.now());b.put("status",400);b.put("error","VALIDATION_ERROR");Map<String,String>e=new LinkedHashMap<>();ex.getBindingResult().getFieldErrors().forEach(x->e.put(x.getField(),x.getDefaultMessage()));b.put("errors",e);return ResponseEntity.badRequest().body(b);} @ExceptionHandler(ConstraintViolationException.class) public ResponseEntity<Map<String,Object>> validation(ConstraintViolationException ex){Map<String,Object>b=new LinkedHashMap<>();b.put("timestamp",Instant.now());b.put("status",400);b.put("error","VALIDATION_ERROR");b.put("message",ex.getMessage());return ResponseEntity.badRequest().body(b);} @ExceptionHandler(IllegalArgumentException.class) public ResponseEntity<Map<String,Object>> bad(IllegalArgumentException ex){Map<String,Object>b=new LinkedHashMap<>();b.put("timestamp",Instant.now());b.put("status",400);b.put("error","BAD_REQUEST");b.put("message",ex.getMessage());return ResponseEntity.badRequest().body(b);}}
